import numpy as np
paths=list(np.load('/app/output/plan.npy',allow_pickle=True))
def merge(paths,maxdist=15,maxlen=150):
 out=[]
 for k in range(16):
  pp=[p for c,p in paths if c==k]
  plen=lambda p:np.linalg.norm(np.diff(p[:,:2],axis=0),axis=1).sum()
  while True:
   best=None
   for i,p in enumerate(pp):
    lp=plen(p)
    if lp>maxlen-10:continue
    for j,q in enumerate(pp):
     if j<=i or lp+plen(q)>maxlen:continue
     for r in range(4):
      pa=p[::-1] if r%2 else p;qa=q[::-1] if r//2 else q
      d=np.linalg.norm(pa[-1,:2]-qa[0,:2])
      if d>maxdist or lp+plen(q)+d>maxlen:continue
      if best is None or d<best[0]:best=(d,i,j,r)
   if best is None:break
   d,i,j,r=best;p=pp[i][::-1] if r%2 else pp[i];q=pp[j][::-1] if r//2 else pp[j]
   a=p[-1].copy();a[2]=.35;b=q[0].copy();b[2]=.35
   pp[i]=np.vstack([p,a,b,q]);pp.pop(j)
  out.extend([(k,p) for p in pp])
 return out
if __name__=='__main__':
 for d in [5,10,15,20]:print(d,len(merge(paths,d)),flush=True)
